def _extract_netloc(
    self,
    netloc: str,
    include_psl_private_domains: bool | None,
    session: requests.Session | None = None,
) -> ExtractResult:
    netloc_with_ascii_dots = (
        netloc.replace("\u3002", "\u002e")
        .replace("\uff0e", "\u002e")
        .replace("\uff61", "\u002e")
    )

    min_num_ipv6_chars = 4
    if (
        len(netloc_with_ascii_dots) >= min_num_ipv6_chars
        and netloc_with_ascii_dots[0] == "["
        and netloc_with_ascii_dots[-1] == "]"
        and looks_like_ipv6(netloc_with_ascii_dots[1:-1])
    ):
        return ExtractResult("", netloc_with_ascii_dots, "", is_private=False, registry_suffix="")

    labels = netloc_with_ascii_dots.split(".")

    tld_extractor = self._get_tld_extractor(session=session)
    suffix_index, is_private = tld_extractor.suffix_index(
        labels, include_psl_private_domains=include_psl_private_domains
    )

    registry_suffix_index = tld_extractor.registry_suffix_index(labels)

    num_ipv4_labels = 4
    if suffix_index == len(labels) == num_ipv4_labels and looks_like_ip(
        netloc_with_ascii_dots
    ):
        return ExtractResult(
            "", netloc_with_ascii_dots, "", is_private, registry_suffix=""
        )

    suffix = ".".join(labels[suffix_index:]) if suffix_index != len(labels) else ""
    subdomain = ".".join(labels[: suffix_index - 1]) if suffix_index >= 2 else ""
    domain = labels[suffix_index - 1] if suffix_index else ""

    registry_suffix = (
        ".".join(labels[registry_suffix_index:])
        if registry_suffix_index != len(labels)
        else ""
    )
    return ExtractResult(subdomain, domain, suffix, is_private, registry_suffix)

